# In-memory SQLite DB — recreated on each startup
_DB = ":memory:"
_conn = sqlite3.connect(_DB, check_same_thread=False)
_conn.row_factory = sqlite3.Row
_conn.executescript(
    "CREATE TABLE users "
    "(id INTEGER PRIMARY KEY, username TEXT, password TEXT, role TEXT);"
)
_conn.executemany(
    "INSERT INTO users VALUES (?,?,?,?)",
    [(1,"alice","lab_alice_pass","user"),
     (2,"bob","lab_bob_pass","user"),
     (3,"admin","lab_admin_pass","admin")]
)
_conn.commit()

